<script setup>
import { onMounted, reactive, ref } from 'vue'
import FloatingWindow from '../components/common/FloatingWindow.vue'
import NeonPanel from '../components/common/NeonPanel.vue'
import { useAppStore } from '../stores/app'

const store = useAppStore(); const approvals = ref([]); const policies = ref([]); const selected = ref(null); const notes = ref(''); const working = ref(false); const detailWindow = ref(false); const policyWindow = ref(false)
const policyDraft = reactive({ name: '', environmentId: 'env-default', approverTeamIds: [], approverUserIds: [], quorum: 1, expiresMinutes: 60, escalationMinutes: 30, escalationUserIds: [], separationOfDuties: true, emergencyEnabled: false, requireChangeTicket: false })
async function refresh() { approvals.value = await store.listApprovals(); policies.value = await store.listApprovalPolicies() }
function open(approval) { selected.value = approval; notes.value = ''; detailWindow.value = true }
function openPolicy(policy = null) { Object.assign(policyDraft, policy ? { ...policy } : { name: 'Environment approval policy', environmentId: store.activeScope.environmentId, approverTeamIds: [], approverUserIds: [], quorum: 1, expiresMinutes: 60, escalationMinutes: 30, escalationUserIds: [], separationOfDuties: true, emergencyEnabled: false, requireChangeTicket: false }); policyWindow.value = true }
async function decide(status) { if (!selected.value) return; working.value = true; try { const result = await store.decideApproval(selected.value.id, status, notes.value); selected.value = result.approval; await refresh(); if (result.approval.status !== 'pending') detailWindow.value = false } finally { working.value = false } }
async function savePolicy() { await store.saveApprovalPolicy(policyDraft); policyWindow.value = false; await refresh() }
function stateColor(status) { return ({ approved: 'success', rejected: 'error', expired: 'error', pending: 'warning' }[status] || 'default') }
onMounted(refresh)
</script>

<template><div class="approval-workspace"><div class="toolbar-row"><div><p class="section-eyebrow">Governed Execution</p><h2 class="page-title">Approval Queue</h2></div><div class="chip-line"><v-btn v-if="store.currentUser?.role === 'admin'" variant="text" prepend-icon="mdi-shield-crown-outline" @click="openPolicy()">Approval Policy</v-btn><v-btn variant="text" prepend-icon="mdi-refresh" @click="refresh">Refresh</v-btn></div></div><NeonPanel subtitle="Human Gate" title="Pending Run Requests"><div class="approval-list"><article v-for="approval in approvals" :key="approval.id" :class="['approval-card', approval.status]"><v-icon :icon="approval.status === 'pending' ? 'mdi-clock-alert-outline' : approval.status === 'approved' ? 'mdi-check-decagram-outline' : 'mdi-close-octagon-outline'" :color="stateColor(approval.status)"/><div><strong>{{ approval.schedule_name || approval.entity_type }}</strong><span>{{ approval.status }} · {{ approval.votes.filter((vote) => vote.decision === 'approved').length }}/{{ approval.quorum }} approvals · requested by {{ approval.requester_name || 'system' }}</span><small>{{ approval.change_ticket || 'No change ticket' }}{{ approval.isEscalated ? ' · escalated' : '' }}{{ approval.expires_at ? ` · expires ${approval.expires_at}` : '' }}</small></div><v-btn v-if="approval.status === 'pending'" size="small" class="glass-button" @click="open(approval)">Review</v-btn><v-chip v-else size="x-small" :color="stateColor(approval.status)" variant="tonal">{{ approval.status }}</v-chip></article><p v-if="!approvals.length" class="empty-state">No approval requests have been queued.</p></div></NeonPanel><FloatingWindow v-model="detailWindow" title="Review Approval Workflow" :width="640" :start-x="350" :start-y="100"><div v-if="selected" class="review"><p class="section-eyebrow">{{ selected.policy?.name || 'Default approval policy' }}</p><h3>{{ selected.schedule_name }}</h3><div class="evidence-grid"><span>Quorum</span><strong>{{ selected.votes.filter((vote) => vote.decision === 'approved').length }} / {{ selected.quorum }}</strong><span>Expiry</span><strong>{{ selected.expires_at || 'No expiry' }}</strong><span>Change</span><strong>{{ selected.change_ticket || 'None' }}</strong><span>Emergency</span><strong>{{ selected.emergency_justification || 'No' }}</strong></div><v-alert v-if="selected.isEscalated" type="warning" density="compact" variant="tonal">Escalation threshold reached. Escalation recipients were recorded in the audit trail.</v-alert><div class="vote-list"><article v-for="vote in selected.votes" :key="vote.id"><strong>{{ vote.voter_name || vote.voter_email }}</strong><span>{{ vote.decision }} · {{ vote.notes || 'No note' }}</span></article><p v-if="!selected.votes.length" class="muted">No votes recorded yet.</p></div><v-textarea v-model="notes" label="Decision evidence / notes" rows="3"/><div class="actions"><v-btn variant="text" @click="detailWindow = false">Close</v-btn><v-btn color="error" variant="text" :loading="working" @click="decide('rejected')">Reject</v-btn><v-btn class="glass-button" :loading="working" @click="decide('approved')">Record Approval</v-btn></div></div></FloatingWindow><FloatingWindow v-model="policyWindow" title="Approval Workflow Policy" :width="680" :start-x="300" :start-y="90"><form class="policy-form" @submit.prevent="savePolicy"><v-text-field v-model="policyDraft.name" label="Policy name"/><v-text-field v-model="policyDraft.environmentId" label="Environment ID" hint="One approval policy per environment" persistent-hint/><v-select v-model="policyDraft.approverTeamIds" :items="store.catalog.teams" item-title="name" item-value="id" label="Approver groups" multiple chips/><v-select v-model="policyDraft.approverUserIds" :items="store.catalog.users" item-title="email" item-value="id" label="Direct approvers" multiple chips/><div class="policy-grid"><v-text-field v-model.number="policyDraft.quorum" type="number" min="1" label="Required approvals"/><v-text-field v-model.number="policyDraft.expiresMinutes" type="number" min="1" label="Default deny after minutes"/><v-text-field v-model.number="policyDraft.escalationMinutes" type="number" min="1" label="Escalate after minutes"/></div><v-select v-model="policyDraft.escalationUserIds" :items="store.catalog.users" item-title="email" item-value="id" label="Escalation recipients" multiple chips/><v-switch v-model="policyDraft.separationOfDuties" color="secondary" density="compact" label="Block requester self-approval"/><v-switch v-model="policyDraft.requireChangeTicket" color="warning" density="compact" label="Require ServiceNow / Jira change ticket"/><v-switch v-model="policyDraft.emergencyEnabled" color="error" density="compact" label="Allow emergency justification when ticket is unavailable"/><div class="actions"><v-btn variant="text" @click="policyWindow = false">Cancel</v-btn><v-btn class="glass-button" type="submit">Save Policy</v-btn></div></form></FloatingWindow></div></template>
<style scoped>.approval-workspace,.approval-list,.review,.policy-form,.vote-list{display:grid;gap:14px}.approval-list{padding:14px}.approval-card{display:grid;grid-template-columns:auto 1fr auto;gap:12px;align-items:center;padding:12px;border:1px solid var(--line);background:rgba(40,211,255,.04)}.approval-card.pending{border-left:2px solid var(--amber)}.approval-card div{display:grid;gap:3px}.approval-card span,.approval-card small,.review p,.empty-state,.muted{color:var(--muted);font-size:.76rem}.approval-card strong,.review h3{margin:0}.actions{display:flex;justify-content:flex-end;gap:8px}.evidence-grid{display:grid;grid-template-columns:auto 1fr;gap:7px 14px;padding:12px;border:1px solid var(--line);background:rgba(40,211,255,.04);font-size:.76rem}.evidence-grid span{color:var(--muted)}.vote-list article{display:flex;justify-content:space-between;gap:10px;padding:9px;border-bottom:1px solid var(--line);font-size:.75rem}.vote-list span{color:var(--muted)}.policy-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}@media(max-width:600px){.policy-grid{grid-template-columns:1fr}.approval-card{grid-template-columns:auto 1fr}.approval-card .v-btn,.approval-card .v-chip{grid-column:2}}</style>
